import React from 'react';

function cppPage(title, lead, concept, code, example, takeaway) {
  return {
    title,
    content: (
      <>
        <p className="lesson-lead">{lead}</p>
        <section className="lesson-topic">
          <h3>Core idea</h3>
          <p>{concept}</p>
          <pre><code>{code}</code></pre>
        </section>
        <section className="lesson-topic">
          <h3>Work through the example</h3>
          <p>{example}</p>
        </section>
        <p className="lesson-takeaway">{takeaway}</p>
      </>
    ),
  };
}

function cppLecture(title, pages) {
  return {
    title,
    pages: pages.map((page) => cppPage(...page)),
  };
}

